DOCUMENT();
############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PCCmacros.pl", "contextCurrency.pl", "contextForm.pl", "parserGraphTool.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
$a = random(960,2400,120); $ymax = (int($a/1000) + 1)*1000; $f = Formula("$a / x"); @pts = map {"{point,($_," . $f->eval(x => $_) . ')}'} (1..6); Context("Currency"); $ac = Currency($a); $gt = GraphTool(join(',', @pts))->with( bBox => [-1, $ymax, 6.5, -100], availableTools => [ "PointTool" ], gridY => 100, ticksDistanceY => 200, snapSizeY => $a/120, showInStatic => 0, xAxisLabel => 'x\\text{ (people)}', yAxisLabel => 'y\\text{ (dollars)}' );
###### # Body ######
BEGIN_PGML A beloved coworker is retiring and you want to give them a gift of week-long vacation rental at the coast that costs [`[$ac]`] for the week. You might end up paying for all of it yourself, but you ask around to see if any of the other office coworkers want to split the cost evenly. The equation [`y=[$f]`] models this situation, where [`x`] people contribute to the gift, and [`y`] is the dollar amount each individual will contribute. Plot a graph of this equation.
[@KeyboardInstructions('Include as many points as you are able to.')@]**
[_]{$gt}{1}
END_PGML
############# # End Problem #############
ENDDOCUMENT();
